// How many pairs of positions (i < j) add up to target?
export function countPairs(nums, target) {
  const seen = new Map();
  let count = 0;
  for (const n of nums) {
    count += seen.get(target - n) ?? 0;
    seen.set(n, (seen.get(n) ?? 0) + 1);
  }
  return count;
}
